package api

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"slices"
	"strings"
	"testing"
	"time"

	"github.com/byjoellobo/nofiltr-pos/internal/auth"
	"github.com/byjoellobo/nofiltr-pos/internal/codegen/ts"
	"github.com/byjoellobo/nofiltr-pos/internal/domain/money"
	"github.com/byjoellobo/nofiltr-pos/internal/domain/order"
	"github.com/byjoellobo/nofiltr-pos/internal/domain/tax"
	"github.com/byjoellobo/nofiltr-pos/internal/hub"
)

// typesFile is the generated file, relative to this package.
const typesFile = "../../web/shared/api-types.ts"

// update rewrites the generated file instead of checking it. `make generate`
// passes it; nothing else should.
var update = flag.Bool("update", false, "rewrite web/shared/api-types.ts")

const header = `// Code generated by internal/api/typescript_test.go. DO NOT EDIT.
//
// The API's request and response types, and the hub's messages, as
// TypeScript. Regenerate with ` + "`make generate`" + `; ` + "`make check`" + ` fails if this
// file and the Go structs disagree.
//
// Money is minor units: an integer of paise or cents, never a float and
// never a decimal string. Render it, do not compute with it.
// Timestamps are RFC 3339 in UTC.`

// eventUnion is order.Event by hand, because its JSON is not its struct:
// MarshalJSON writes the envelope with the payload nested, and which
// payload it is depends on the type. The payload interfaces themselves are
// generated, and eventTypes below is checked against the domain's own list,
// so an event type added without a line here fails this test.
const eventUnion = `export interface OrderEventOf<T extends OrderEventType, P> {
  seq: number;
  type: T;
  at: string;
  actor_id: number;
  device_id: number;
  payload: P;
}

/** One event of an order's stream, discriminated by its type. */
export type OrderEvent =
%s;`

// eventTypes pairs every event type with the payload it carries.
var eventTypes = []struct {
	Type    order.Type
	Payload any
	TS      string
}{
	{order.TypeOrderOpened, order.OrderOpened{}, "OrderOpened"},
	{order.TypeLineAdded, order.LineAdded{}, "LineAdded"},
	{order.TypeLineQtyChanged, order.LineQtyChanged{}, "LineQtyChanged"},
	{order.TypeLineVoided, order.LineVoided{}, "LineVoided"},
	{order.TypeLineComped, order.LineComped{}, "LineComped"},
	{order.TypeDiscountApplied, order.DiscountApplied{}, "DiscountApplied"},
	{order.TypeNoteAdded, order.NoteAdded{}, "NoteAdded"},
	{order.TypeCourseFired, order.CourseFired{}, "CourseFired"},
	{order.TypeTicketSent, order.TicketSent{}, "TicketSent"},
	{order.TypePaymentTendered, order.PaymentTendered{}, "PaymentTendered"},
	{order.TypePaymentVoided, order.PaymentVoided{}, "PaymentVoided"},
	{order.TypeInvoiceIssued, order.InvoiceIssued{}, "InvoiceIssued"},
	{order.TypeRefundIssued, order.RefundIssued{}, "RefundIssued"},
	{order.TypeOrderClosed, order.OrderClosed{}, "OrderClosed"},
	{order.TypeOrderReopened, order.OrderReopened{}, "OrderReopened"},
}

// errorCodes is every code the API answers with. A client switches on
// these, so they are a union rather than a bare string.
var errorCodes = []ErrorCode{
	CodeNotFound, CodeMethodNotAllowed, CodeInternal, CodeInvalidRequest,
	CodeUnauthenticated, CodeDeviceRevoked, CodeInvalidPairingCode,
	CodeInvalidPIN, CodeLockedOut, CodeSignInRequired, CodeRateLimited, CodeForbidden,
	CodeOrderNotFound, CodeLineNotFound, CodeLineNotActive, CodePaymentNotFound,
	CodePaymentNotCaptured, CodeOrderClosed, CodeOrderNotClosed, CodeQtyMismatch,
	CodeBalanceDue, CodeOverTender, CodeOverRefund, CodeDiscountTooLarge,
	CodeAlreadyInvoiced, CodeCourseAlreadyFired, CodeNothingToSend,
	CodeInvalidTransition, CodeInvalidPayload, CodeCurrencyMismatch,
	CodeIdempotencyKeyReused, CodeVenueNotConfigured,
}

// generate builds the whole file.
func generate() (*ts.Generator, error) {
	g := ts.New(ts.Options{
		Header: header,
		Inline: map[reflect.Type]string{
			reflect.TypeOf(time.Time{}):       "string",
			reflect.TypeOf(json.RawMessage{}): "unknown",
		},
		Names: map[reflect.Type]string{
			// Two packages have an Error; the API's is the one clients see
			// most, and the hub's says which socket message it is.
			reflect.TypeOf(Error{}):            "ApiError",
			reflect.TypeOf(hub.ErrorMessage{}): "StreamErrorMessage",
			reflect.TypeOf(errorBody{}):        "ApiErrorBody",
			reflect.TypeOf(amount{}):           "MoneyInput",
			reflect.TypeOf(money.Amount{}):     "Money",
			reflect.TypeOf(order.Modifier{}):   "LineModifier",
		},
	})

	// The vocabularies first: a client switches on all of these.
	unions := []struct {
		name   string
		sample any
		values []string
	}{
		{"ErrorCode", CodeInternal, asStrings(errorCodes)},
		{"OrderStatus", order.StatusOpen, []string{
			string(order.StatusOpen), string(order.StatusHeld), string(order.StatusSettling),
			string(order.StatusClosed), string(order.StatusReopened),
		}},
		{"OrderChannel", order.ChannelCounter, []string{
			string(order.ChannelCounter), string(order.ChannelQRTable), string(order.ChannelWeb),
			string(order.ChannelKiosk), string(order.ChannelAggregator),
		}},
		{"LineStatus", order.LineStatusActive, []string{
			string(order.LineStatusActive), string(order.LineStatusVoided), string(order.LineStatusComped),
		}},
		{"PaymentStatus", order.PaymentStatusPending, []string{
			string(order.PaymentStatusPending), string(order.PaymentStatusCaptured),
			string(order.PaymentStatusVoided), string(order.PaymentStatusRefunded),
		}},
		{"PaymentMethod", order.PaymentCash, paymentMethods()},
		{"DiscountScope", order.ScopeLine, []string{string(order.ScopeLine), string(order.ScopeOrder)}},
		{"DiscountKind", order.DiscountPercent, []string{string(order.DiscountPercent), string(order.DiscountAmount)}},
		{"TaxPricing", tax.Inclusive, []string{string(tax.Inclusive), string(tax.Exclusive)}},
		{"DeviceKind", auth.KindTerminal, asStrings([]auth.DeviceKind{
			auth.KindTerminal, auth.KindKitchen, auth.KindBackOffice, auth.KindGuest,
		})},
		{"Permission", auth.PermOrderOpen, permissions()},
		{"OrderEventType", order.TypeOrderOpened, eventTypeNames()},
		{"StreamMessageType", hub.MsgHello, asStrings([]hub.MessageType{
			hub.MsgHello, hub.MsgSubscribe, hub.MsgWelcome, hub.MsgEvent, hub.MsgCaughtUp, hub.MsgError,
		})},
	}
	for _, u := range unions {
		if err := g.Union(u.name, u.sample, u.values...); err != nil {
			return nil, err
		}
	}

	// Money, then the event payloads, then the event itself.
	if _, err := g.Add(money.Amount{}); err != nil {
		return nil, err
	}
	if err := g.Raw("currencyExponents", currencyExponents(), nil); err != nil {
		return nil, err
	}
	var arms string
	for _, e := range eventTypes {
		if _, err := g.Add(e.Payload); err != nil {
			return nil, err
		}
		arms += fmt.Sprintf("  | OrderEventOf<'%s', %s>\n", e.Type, e.TS)
	}
	if err := g.Raw("OrderEvent", fmt.Sprintf(eventUnion, arms[:len(arms)-1]), order.Event{}); err != nil {
		return nil, err
	}

	// Everything the API takes and answers with.
	roots := []any{
		// Errors and pairing.
		Error{}, errorBody{}, pairRequest{}, deviceResponse{}, pairResponse{},
		newCodeRequest{}, pairingCodeResponse{},
		// Staff.
		staffResponse{}, staffListResponse{}, signInRequest{}, sessionResponse{},
		// Orders: what is sent.
		Override{}, amount{}, openOrderRequest{}, addLineRequest{}, changeQtyRequest{},
		voidLineRequest{}, discountRequest{}, addNoteRequest{}, sendTicketRequest{},
		tenderRequest{}, voidPaymentRequest{}, refundRequest{}, reopenRequest{},
		// Orders: what comes back.
		lineResponse{}, noteResponse{}, ticketResponse{}, tenderResponse{},
		refundResponse{}, invoiceResponse{}, discountResponse{}, totalsResponse{},
		taxResponse{}, orderResponse{}, commandResponse{},
		// The stream.
		hub.ClientMessage{}, hub.WelcomeMessage{}, hub.EventMessage{},
		hub.CaughtUpMessage{}, hub.ErrorMessage{},
	}
	for _, root := range roots {
		if _, err := g.Add(root); err != nil {
			return nil, err
		}
	}
	return g, nil
}

// currencyExponents is money's exponent table as a TypeScript constant, so
// a frontend turns minor units into a displayed amount exactly as the server
// does. A yen shown as 12.34 when it means 1234 is the failure this prevents.
func currencyExponents() string {
	table := money.Exponents()
	codes := make([]string, 0, len(table))
	for code := range table {
		codes = append(codes, code)
	}
	slices.Sort(codes)

	var b strings.Builder
	b.WriteString("/** Decimal places of a currency's minor unit, where not the default. ISO 4217. */\n")
	b.WriteString("export const currencyExponents: Readonly<Record<string, number>> = {\n")
	for _, code := range codes {
		fmt.Fprintf(&b, "  %s: %d,\n", code, table[code])
	}
	b.WriteString("};\n\n")
	fmt.Fprintf(&b, "export const defaultCurrencyExponent = %d;\n", money.DefaultExponent)
	return b.String()
}

// asStrings is any list of named string constants as plain strings. It is
// not called strings, which would collide with the import in this package.
func asStrings[T ~string](values []T) []string {
	out := make([]string, len(values))
	for i, v := range values {
		out[i] = string(v)
	}
	return out
}

func paymentMethods() []string {
	return asStrings([]order.PaymentMethod{
		order.PaymentCash, order.PaymentCard, order.PaymentUPI, order.PaymentOther,
	})
}

func permissions() []string { return asStrings(auth.Permissions()) }

func eventTypeNames() []string {
	out := make([]string, len(eventTypes))
	for i, e := range eventTypes {
		out[i] = string(e.Type)
	}
	return out
}

// TestTypeScriptTypes generates web/shared/api-types.ts and fails if the
// committed file is not what the Go structs produce. With -update it writes
// the file instead, which is what `make generate` runs.
//
// This is the whole drift guard: `make check` runs the tests, so a struct
// changed without regenerating fails the build rather than reaching a
// frontend as a type that quietly lies.
func TestTypeScriptTypes(t *testing.T) {
	g, err := generate()
	if err != nil {
		t.Fatalf("generating: %v", err)
	}
	want := g.Source()

	if *update {
		if err := os.MkdirAll(filepath.Dir(typesFile), 0o750); err != nil {
			t.Fatalf("making the directory: %v", err)
		}
		if err := os.WriteFile(typesFile, []byte(want), 0o600); err != nil {
			t.Fatalf("writing %s: %v", typesFile, err)
		}
		t.Logf("wrote %s: %d declarations", typesFile, len(g.Names()))
		return
	}

	got, err := os.ReadFile(typesFile)
	if err != nil {
		t.Fatalf("%v\n\nRun `make generate` to write it.", err)
	}
	if string(got) != want {
		t.Errorf("%s is not what the Go structs generate.\n\nRun `make generate` and commit the result.\n%s",
			typesFile, firstDifference(string(got), want))
	}
}

// TestEveryEventTypeIsGenerated is what stops the hand-written union
// falling behind: the domain knows its own event types, and each one must
// appear here.
func TestEveryEventTypeIsGenerated(t *testing.T) {
	listed := map[order.Type]bool{}
	for _, e := range eventTypes {
		listed[e.Type] = true
		if got := e.Payload.(order.Payload).EventType(); got != e.Type {
			t.Errorf("%s is paired with a %s payload", e.Type, got)
		}
	}
	for _, typ := range order.Types() {
		if !listed[typ] {
			t.Errorf("event type %s is not in eventTypes, so TypeScript will not know it", typ)
		}
	}
}

// firstDifference points at the line that differs, since a whole-file diff
// in a test log is unreadable.
func firstDifference(got, want string) string {
	gotLines, wantLines := splitLines(got), splitLines(want)
	for i := range max(len(gotLines), len(wantLines)) {
		g, w := at(gotLines, i), at(wantLines, i)
		if g != w {
			return fmt.Sprintf("\nline %d:\n  committed: %q\n  generated: %q", i+1, g, w)
		}
	}
	return ""
}

func splitLines(s string) []string { return strings.Split(s, "\n") }

func at(lines []string, i int) string {
	if i < len(lines) {
		return lines[i]
	}
	return "(end of file)"
}
